const LOCAL = "Restaurante Centro";
const rnd = (min, max) => Math.random() * (max - min) + min;
const tickets = [];

for (let i = 0; i < 140; i++) {
  const delivery = Math.random() < 0.28;
  const comensales = delivery ? 1 : Math.round(rnd(1, 5));
  const importe = delivery ? rnd(18, 45) : rnd(12, 34) * comensales;
  tickets.push({
    id: 1000 + i,
    canal: delivery ? 'delivery' : 'local',
    comensales,
    importe: Math.round(importe * 100) / 100,
    descuento: Math.random() < 0.12 ? Math.round(importe * rnd(0.05, 0.20) * 100) / 100 : 0,
    invitacion: Math.random() < 0.04,
    anulado: Math.random() < 0.03,
  });
}

const ventaDia = tickets
  .filter(t => !t.anulado && !t.invitacion)
  .reduce((s, t) => s + t.importe - t.descuento, 0);

return [{
  json: {
    local: LOCAL,
    fecha: new Date(Date.now() - 86400000).toLocaleDateString('es-ES'),
    acumuladoMes: 84210.55,
    ventaSemanaPasada: ventaDia * (0.88 + Math.random() * 0.2),
    tickets,
  }
}];

const d = $input.first().json;

const eur = n => n.toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' €';
const pct = n => n.toLocaleString('es-ES', {minimumFractionDigits: 1, maximumFractionDigits: 1}) + '%';

const anulados = d.tickets.filter(t => t.anulado);
const invitaciones = d.tickets.filter(t => !t.anulado && t.invitacion);
const validos = d.tickets.filter(t => !t.anulado && !t.invitacion);

const neto = t => t.importe - t.descuento;
const suma = (arr, f) => arr.reduce((s, x) => s + f(x), 0);

const ventaNeta = suma(validos, neto);
const descuentos = suma(validos, t => t.descuento);
const comensales = suma(validos, t => t.comensales);

const local = validos.filter(t => t.canal === 'local');
const delivery = validos.filter(t => t.canal === 'delivery');
const ventaLocal = suma(local, neto);
const ventaDelivery = suma(delivery, neto);

const variacion = ((ventaNeta - d.ventaSemanaPasada) / d.ventaSemanaPasada) * 100;

return [{
  json: {
    local: d.local,
    fecha: d.fecha,
    ventaNeta: eur(ventaNeta),
    variacion: (variacion >= 0 ? '+' : '') + pct(variacion),
    subiendo: variacion >= 0,
    acumuladoMes: eur(d.acumuladoMes + ventaNeta),
    ventaLocal: eur(ventaLocal),
    pesoLocal: pct(ventaLocal / ventaNeta * 100),
    ventaDelivery: eur(ventaDelivery),
    pesoDelivery: pct(ventaDelivery / ventaNeta * 100),
    ticketMedio: eur(ventaNeta / validos.length),
    comensales,
    gastoComensal: eur(ventaNeta / comensales),
    descuentos: eur(descuentos),
    pesoDescuentos: pct(descuentos / (ventaNeta + descuentos) * 100),
    numInvitaciones: invitaciones.length,
    importeInvitaciones: eur(suma(invitaciones, t => t.importe)),
    numAnulados: anulados.length,
    importeAnulados: eur(suma(anulados, t => t.importe)),
  }
}];

const k = $input.first().json;

const mensaje = `📊 *CIERRE ${k.fecha}* · ${k.local}

*VENTA NETA: ${k.ventaNeta}*
${k.subiendo ? '🔼' : '🔻'} ${k.variacion} vs. mismo día semana pasada
Acumulado mes: ${k.acumuladoMes}

*CANALES*
🍽️ Local: ${k.ventaLocal} (${k.pesoLocal})
🛵 Delivery: ${k.ventaDelivery} (${k.pesoDelivery})

*TICKET*
Medio: ${k.ticketMedio} · Comensales: ${k.comensales}
Gasto/comensal: ${k.gastoComensal}

*CONTROL*
Descuentos: ${k.descuentos} (${k.pesoDescuentos})
Invitaciones: ${k.numInvitaciones} · ${k.importeInvitaciones}
Anulaciones: ${k.numAnulados} · ${k.importeAnulados}`;

return [{ json: { mensaje } }];
